import React, { useEffect, useState } from "react";
import axios from "axios";

export default function AdminOrders() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchOrders = async () => {
    try {
      const token = localStorage.getItem("admintoken");

      const response = await axios.get("http://localhost:4000/admin/orders", {
        headers: { Authorization: `Bearer ${token}` },
      });

      setOrders(response.data);
      setLoading(false);
    } catch (err) {
      console.error("❌ Orders Fetch Error:", err);
      setError("Failed to fetch orders. Ensure admin token exists.");
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  return (
    <div style={containerStyle}>
      <h2 style={titleStyle}>📦 Paid Orders (Admin)</h2>

      {loading && <p style={loadingStyle}>Loading orders...</p>}
      {error && <p style={errorStyle}>{error}</p>}

      {!loading && !error && orders.length === 0 && (
        <p style={noOrdersStyle}>No Paid Orders Found</p>
      )}

      {!loading && !error && orders.length > 0 && (
        <table style={tableStyle}>
          <thead>
            <tr>
              <th style={thStyle}>Order ID</th>
              <th style={thStyle}>Customer</th>
              <th style={thStyle}>Email</th>
              <th style={thStyle}>Address</th>
              <th style={thStyle}>Amount</th>
              <th style={thStyle}>Payment ID</th>
              <th style={thStyle}>Created At</th>
            </tr>
          </thead>

          <tbody>
            {orders.map((item) => (
              <tr key={item.id}>
                <td style={tdStyle}>{item.orderid}</td>
                <td style={tdStyle}>{item.customer_name}</td>
                <td style={tdStyle}>{item.customer_email}</td>
                <td style={tdStyle}>{item.customer_address || "N/A"}</td>

                {/* ✅ Values updated to match backend fields */}
                <td style={{ ...tdStyle, fontWeight: "bold", color: "#2563eb" }}>
                  ₹{item.amount}
                </td>

                <td style={tdStyle}>{item.payment_id}</td>

                <td style={tdStyle}>
                  {new Date(item.created_at).toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

/* ================= INLINE CSS ================= */

const containerStyle = {
  width: "95%",
  margin: "20px auto",
  fontFamily: "Arial, sans-serif",
};

const titleStyle = {
  fontSize: "22px",
  fontWeight: "700",
  marginBottom: "20px",
};

const loadingStyle = {
  color: "#2563eb",
  fontWeight: "600",
};

const errorStyle = {
  color: "#e11d48",
  fontWeight: "600",
};

const noOrdersStyle = {
  fontStyle: "italic",
  color: "#6b7280",
};

const tableStyle = {
  width: "100%",
  borderCollapse: "collapse",
  backgroundColor: "#fff",
  boxShadow: "0px 2px 10px rgba(0,0,0,0.1)",
};

const thStyle = {
  padding: "10px",
  backgroundColor: "#1f2937",
  color: "#fff",
  textAlign: "left",
  borderBottom: "3px solid #111827",
};

const tdStyle = {
  padding: "10px",
  borderBottom: "1px solid #ddd",
};
